# Normalise drawplanar attribute names across planarity versions:
# newer releases expose 'vertex_position'/'vertex_start'/'vertex_end'
# (and 'edge_*') instead of the older 'pos'/'start'/'end'.
for _, _data in g.nodes(data=True):
    for _old, _new in (('vertex_position', 'pos'),
                       ('vertex_start', 'start'),
                       ('vertex_end', 'end')):
        if _new not in _data and _old in _data:
            _data[_new] = _data[_old]
for _, _, _data in g.edges(data=True):
